$(document).ready(function () {

    var gvControleValores = $('table[id*=gvControleValores]');
    var itens_Popula = [];
    var itens_ControleValores = [];
    var sidTabela = $('[id*=hddidTabela]').val() || '0';
    var idTipoTabela = parseInt($('[id*=hddTipoTabela]').val()) || 0;
    var colunasDinamicas = '';
    var cabecalho_1 = '';
    var cabecalho_2 = '';

    async function popula_ControleValores() {
        await $.ajax({
            url: "/App/Paginas/Comercial/Tabelas_Detalhe.aspx/Get_PopularAba_ControleValores",
            data: JSON.stringify({ itens: itens_Popula, sidTabela: sidTabela }),
            type: 'POST',
            dataType: 'json',
            contentType: 'application/json; charset=utf-8',
            success: function (response) {
                if (response && response.d) {
                    let json = JSON.parse(response.d);

                    itens_ControleValores = json.itens;
                    colunasDinamicas = json.colunas;
                    cabecalho_1 = json.cabecalho_1;
                    cabecalho_2 = json.cabecalho_2;
                } else {
                    itens_ControleValores = [];
                    colunasDinamicas = '';
                    cabecalho_1 = '';
                    cabecalho_2 = '';
                    $('[id*=MensagemControleValores]').find('.alert-warning').removeClass('invisivel');
                    $('[id*=MensagemControleValores]').find('.alert-warning').html('<b>Aviso: </b>Não foram encontrados Itens ou Tabelas vinculadas para serem exibidos!');
                }
            },
            error: function (error) {
                $('[id*=MensagemPagina]').find('.alert-warning').removeClass('invisivel');
                $('[id*=MensagemPagina]').find('.alert-danger').html("<b>Erro: </b>Houve um erro ao Popular a Aba de Controle de Valores: " + error);
            }
        })
    }

    window.gvControleValores_DataBind = async function (itens) {

        itens_Popula = itens;

        atualizaLegenda();
        await popula_ControleValores();

        let colunasFinal = eval(`[${colunasDinamicas.trim().replace(/,\s*$/, '')}]`);

        if ($.fn.DataTable.isDataTable(gvControleValores)) {
            let table = gvControleValores.DataTable();
            table.clear();
            table.rows.add(itens_ControleValores);
            table.draw(false);
        } else {
            gvControleValores.DataTable({
                data: itens_ControleValores,
                columns: [
                    {
                        data: 'IdItem', title: 'ID',
                        createdCell: function (td) {
                            $(td).css({ 'width': '2%', 'min-width': '100px', 'text-align': 'center' });
                        }
                    },
                    {
                        data: 'SCodigo', title: 'Código',
                        createdCell: function (td) {
                            $(td).css({ 'width': '15%', 'min-width': '200px' });
                        }
                    },
                    {
                        data: 'SDscProduto', title: 'Descrição',
                        createdCell: function (td) {
                            $(td).css({ 'width': '25%', 'min-width': '300px' });
                        }
                    }
                ].concat(colunasFinal),
                headerCallback: function (thead) {
                    $(thead).addClass('invisivel');
                    if ($(thead).closest('thead').find('tr.cabecalho_personalizado').length <= 0) {
                        $(thead).closest('thead').append(`<tr class='cabecalho_personalizado'><th colspan='3'></th>${cabecalho_1}</tr>`);
                        $(thead).closest('thead').append(`<tr class='cabecalho_personalizado'><th class='sorting' >ID</th><th class='sorting'>Código</th><th class='sorting'>Descrição</th>${cabecalho_2}</tr>`);

                        $(thead).closest('thead').find('tr.cabecalho_personalizado:last th').each(function (index) {
                            $(this).on('click', function () {
                                $(thead).closest('thead').find('tr.invisivel th').eq(index).trigger('click');
                            });
                        });
                    }
                },
                paging: true,
                scrollCollapse: true,
                scrollX: true,
                scrollY: false,
                pageLength: 100,
                lengthMenu: [[10, 50, 100, 500, 1000, 5000, 10000, -1], [10, 50, 100, 500, '1.000', '5.000', '10.000', 'Todos']],
                searching: true,
                bLengthChange: true,
                order: [[0, 'asc']],
                info: false,
                language: { url: 'https://cdn.datatables.net/plug-ins/1.11.5/i18n/pt-BR.json' }
            });
        }
    }

    $.fn.dataTable.ext.search.push(function (settings, data, dataIndex) {
        var rowData = settings.aoData[dataIndex]._aData;

        if (settings.sTableId.includes('gvControleValores')) {
            var descricao = $('[id*=txtControle_Filtro]').length > 0 ? $('[id*=txtControle_Filtro]').val().toLowerCase().trim() : '';
            var tipo = $('[id*=ddlControle_Filtro_Tipo] :selected').length > 0 ? $('[id*=ddlControle_Filtro_Tipo] :selected').text().toLowerCase().trim() : 'todos';
            var unidade = $('[id*=ddlControle_Filtro_Unidade]').length > 0 ? $('[id*=ddlControle_Filtro_Unidade]').val().toLowerCase().trim() : '0';
            var grupo = $('[id*=ddlControle_Filtro_Grupo]').length > 0 ? $('[id*=ddlControle_Filtro_Grupo]').val() : -1;
            var familia = $('[id*=ddlControle_Filtro_Familia]').length > 0 ? $('[id*=ddlControle_Filtro_Familia]').val() : -1;
            var idFiltro = parseInt($('[id*=hddFiltro_ID]').val() || 0);

            if (descricao != '' && !rowData.SCodigoComDescricao.toLowerCase().trim().includes(descricao)) {
                return false;
            }
            if (!tipo.toLowerCase().trim().includes('todos') && !rowData.TipoProduto.toLowerCase().trim().includes(tipo)) {
                return false;
            }
            if (unidade != '0' && !rowData.SUnidade.toLowerCase().trim().includes(unidade)) {
                return false;
            }
            if (grupo != -1 && rowData.IdGrupoProduto != grupo) {
                return false;
            }
            if (familia != -1 && rowData.IdFamiliaProduto != familia) {
                return false;
            }
            if (idFiltro > 0 && rowData.IdItem != idFiltro) {
                return false;
            }
        }

        return true;
    });

    gvControleValores.on('draw.dt', function () {

        // ---------------- Estilos para os campos de N° de Itens e Filtro
        var nItens = $('.dataTables_length[id*="gvControleValores"]');
        var filtro = $('.dataTables_filter[id*="gvControleValores"]');
        nItens.css({ 'margin-right': '0.5%', 'text-align': 'left', 'width': '9.5%' });
        filtro.css('width', '90%');
        nItens.find('label').contents().filter(function () { return this.nodeType === Node.TEXT_NODE; }).each(function (index) { if (index === 0) { this.nodeValue = 'N° de Itens'; } else { this.nodeValue = ''; } });
        nItens.find('label').css({ 'width': '100%', 'text-align': 'left' });
        nItens.find('label').find('select').addClass('form-control');
        filtro.find('label').css({ 'display': 'flex', 'flex-wrap': 'wrap', 'width': '25%' });
        filtro.find('label').find('input').addClass('form-control');

        // ---------------- Aplicando Tooltip
        $('div.tooltip').css('display', 'none');
        $('[data-toggle=tooltip]').tooltip();

        // ---------------- Aplicando Máscaras
        aplicarMascaras_Controle();

    });

    function aplicarMascaras_Controle() {
        const mascaras_Controle = [
            { seletor: '.totalControle', formato: '999.999.999.999,99' }
        ];

        mascaras_Controle.forEach(function (mascara) {
            if ($(mascara.seletor).length > 0) {
                $(mascara.seletor).off('mask').unmask();
                $(mascara.seletor).mask(mascara.formato, { reverse: true });
            }
        });
    }

    function atualizaLegenda() {
        let cell_Legenda1 = $('[id*=cell_Legenda1]');
        let cell_Legenda2 = $('[id*=cell_Legenda2]');
        let cell_Legenda3 = $('[id*=cell_Legenda3]');
        let cell_Legenda4 = $('[id*=cell_Legenda4]');
        let cell_Legenda5 = $('[id*=cell_Legenda5]');
        let cell_Legenda10 = $('[id*=cell_Legenda10]');
        let cell_Legenda11 = $('[id*=cell_Legenda11]');

        cell_Legenda1.addClass('invisivel');
        cell_Legenda2.addClass('invisivel');
        cell_Legenda3.addClass('invisivel');
        cell_Legenda4.addClass('invisivel');
        cell_Legenda5.addClass('invisivel');
        cell_Legenda10.addClass('invisivel');
        cell_Legenda11.addClass('invisivel');

        switch (idTipoTabela) {
            case 2:
                cell_Legenda1.removeClass('invisivel');
                cell_Legenda2.removeClass('invisivel');
                cell_Legenda3.removeClass('invisivel');
                cell_Legenda10.removeClass('invisivel');
                cell_Legenda11.removeClass('invisivel');
                break;
            case 3:
                cell_Legenda1.removeClass('invisivel');
                cell_Legenda3.removeClass('invisivel');
                cell_Legenda11.removeClass('invisivel');
                break;
            case 4:
                cell_Legenda1.removeClass('invisivel');
                cell_Legenda3.removeClass('invisivel');
                cell_Legenda4.removeClass('invisivel');
                cell_Legenda10.removeClass('invisivel');
                cell_Legenda11.removeClass('invisivel');
                break;
            case 5:
                cell_Legenda1.removeClass('invisivel');
                cell_Legenda2.removeClass('invisivel');
                cell_Legenda3.removeClass('invisivel');
                cell_Legenda5.removeClass('invisivel');
                cell_Legenda10.removeClass('invisivel');
                cell_Legenda11.removeClass('invisivel');
                break;
        }
    }

    $('[id*=ddlControle_Filtro]').on('change', function () {
        gvControleValores.DataTable().draw();
    });

    $('[id*=txtControle_Filtro]').on('input', function () {
        gvControleValores.DataTable().draw();
    });

    $('[id*=cmdControle_Filtro]').on('click', function (e) {
        e.preventDefault();
        $(this).toggleClass('btn-info btn-primary');
        $(this).val($(this).hasClass('btn-info') ? 'Filtrar Itens' : 'Fechar Filtros');
        $('[id*=divControle_Filtro]').toggleClass('invisivel');
    });

    // Barras de Scroll sincronizadas
    var topScroll = $('.scroll_top');
    var bottomScroll = $('.scroll_bottom');
    var scrollSync = $('.scroll_sync');

    function adjustTopScrollWidth() {
        scrollSync.width(bottomScroll[0].scrollWidth);
    }

    topScroll.on('scroll', function () {
        bottomScroll.scrollLeft(topScroll.scrollLeft());
    });

    bottomScroll.on('scroll', function () {
        topScroll.scrollLeft(bottomScroll.scrollLeft());
    });

    adjustTopScrollWidth();
    $(window).on('resize', adjustTopScrollWidth);

});